import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { buildCatalog, serializeCatalog } from "./catalog-manifest";
import { checkReleaseMeta } from "./check-release-meta";

/// Generated files are checked, not edited. `src/bindings.ts` must keep its generator header, `catalog.json` must
/// match what its generator builds from the definitions, every command in the canonical registry must have its
/// autogenerated permission file and capability entry, and `src-tauri/gen` stays ignored. `src-tauri/commands.txt` is
/// the one list build.rs, the Rust builder and this guard all read.
const root = join(import.meta.dir, "..");
const TOML = /\.toml$/;
const problems: string[] = [];

const bindings = join(root, "src", "bindings.ts");

if (!existsSync(bindings)) {
	problems.push("src/bindings.ts is missing");
} else if (!readFileSync(bindings, "utf8").startsWith("// This file has been generated by Tauri Specta.")) {
	problems.push("src/bindings.ts lost its generated header");
}

const catalog = join(root, "catalog.json");

if (!existsSync(catalog)) {
	problems.push("catalog.json is missing; run `bun run catalog`");
} else if (readFileSync(catalog, "utf8") !== serializeCatalog(buildCatalog(root))) {
	problems.push("catalog.json is stale; run `bun run catalog`");
}

const registry = join(root, "src-tauri", "commands.txt");
const capabilityFile = join(root, "src-tauri", "capabilities", "default.json");

if (!existsSync(registry)) {
	problems.push("src-tauri/commands.txt is missing");
} else if (!existsSync(capabilityFile)) {
	problems.push("src-tauri/capabilities/default.json is missing");
} else {
	// One `alias::name` per line; the same trivial parse build.rs uses. Comments and blank lines are ignored.
	const commands = readFileSync(registry, "utf8")
		.split("\n")
		.map((line) => line.trim())
		.filter((line) => line !== "" && !line.startsWith("#"))
		.map((line) => {
			const name = line.split("::").at(-1);
			return name === undefined || name === "" ? line : name;
		});
	const expected = commands.map((name) => `allow-${name.replaceAll("_", "-")}`);
	const expectedSet = new Set(expected);

	const permissions = new Set(readdirSync(join(root, "src-tauri", "permissions", "autogenerated")).map((name) => name.replace(TOML, "")));

	for (const command of commands) {
		if (!permissions.has(command)) problems.push(`no autogenerated permission for ${command}`);
	}

	for (const permission of permissions) {
		if (!commands.includes(permission)) problems.push(`stale autogenerated permission ${permission}`);
	}

	const capability: unknown = JSON.parse(readFileSync(capabilityFile, "utf8"));
	const granted = typeof capability === "object" && capability !== null && "permissions" in capability ? capability.permissions : undefined;
	// Only our own permissions are bare `allow-*`: the core and plugin ones are namespaced with a `:`.
	const grantedCommands = Array.isArray(granted)
		? granted.filter((entry): entry is string => typeof entry === "string" && entry.startsWith("allow-") && !entry.includes(":"))
		: [];
	for (const permission of expected) {
		if (!grantedCommands.includes(permission)) problems.push(`${permission} is missing from capabilities/default.json`);
	}

	for (const permission of grantedCommands) {
		if (!expectedSet.has(permission)) problems.push(`stale ${permission} in capabilities/default.json`);
	}
}

const ignore = [readFileSync(join(root, ".gitignore"), "utf8"), readFileSync(join(root, "src-tauri", ".gitignore"), "utf8")].join("\n");

if (!(ignore.includes("gen/schemas") || ignore.includes("src-tauri/gen/"))) {
	problems.push("src-tauri/gen/schemas is not ignored");
}

checkReleaseMeta(problems);

if (problems.length > 0) {
	process.stderr.write(`${problems.join("\n")}\n`);
	process.exit(1);
}

process.stdout.write("Generated files passed.\n");
